-- =============================================================================
-- 034 : RCP BDPM condensé → matrice_medicaments (Cardio DEUST 2A)
-- Généré par sql/ops/cardio_rcp_matrice_gen.mjs — NE PAS éditer à la main.
-- Matrice / référentiel uniquement ; publications DEUST = source cours (035).
-- EI : fréquents ou rares graves. Idempotent (jp_fill sans doublon).
-- =============================================================================

CREATE OR REPLACE FUNCTION pg_temp.jp_ent(p_table text, p_valeur text)
RETURNS uuid LANGUAGE plpgsql AS $$
DECLARE v_id uuid; v_norm text := jeupharma.normaliser_valeur(p_valeur);
BEGIN
  EXECUTE format('SELECT id FROM jeupharma.%I WHERE valeur_norm = $1 AND actif LIMIT 1', p_table) INTO v_id USING v_norm;
  IF v_id IS NULL THEN
    EXECUTE format('INSERT INTO jeupharma.%I (valeur, valeur_norm) VALUES ($1, $2) RETURNING id', p_table) INTO v_id USING p_valeur, v_norm;
  END IF;
  RETURN v_id;
END $$;

CREATE OR REPLACE FUNCTION pg_temp.jp_fill(p_matrice uuid, p_champ text, p_vals text[])
RETURNS void LANGUAGE plpgsql AS $$
DECLARE v_tbl text; v_jt text; v_fk text; v_id uuid; i int;
BEGIN
  SELECT t.ent, t.jt, t.fk INTO v_tbl, v_jt, v_fk FROM (VALUES
    ('secteurs','secteurs_therapeutiques','matrice_secteurs_therapeutiques','secteur_therapeutique_id'),
    ('ct','classes_therapeutiques','matrice_classes_therapeutiques','classe_therapeutique_id'),
    ('cp','classes_pharmacologiques','matrice_classes_pharmacologiques','classe_pharmacologique_id'),
    ('ind','indications','matrice_indications','indication_id'),
    ('ci','contre_indications','matrice_contre_indications','contre_indication_id'),
    ('ei','effets_indesirables','matrice_effets_indesirables','effet_indesirable_id'),
    ('pre','precautions_emploi','matrice_precautions_emploi','precaution_emploi_id'),
    ('inter','interactions','matrice_interactions','interaction_id'),
    ('surv','surveillances','matrice_surveillances','surveillance_id'),
    ('noms','noms_commerciaux','matrice_noms_commerciaux','nom_commercial_id')
  ) AS t(champ, ent, jt, fk) WHERE t.champ = p_champ;
  IF v_tbl IS NULL THEN RAISE EXCEPTION 'champ inconnu %', p_champ; END IF;
  IF p_vals IS NULL THEN RETURN; END IF;
  FOR i IN 1 .. coalesce(array_length(p_vals, 1), 0) LOOP
    v_id := pg_temp.jp_ent(v_tbl, p_vals[i]);
    EXECUTE format(
      'INSERT INTO jeupharma.%I (matrice_id, %I, ordre) SELECT $1, $2, $3 WHERE NOT EXISTS (SELECT 1 FROM jeupharma.%I WHERE matrice_id = $1 AND %I = $2)',
      v_jt, v_fk, v_jt, v_fk) USING p_matrice, v_id, i - 1;
  END LOOP;
END $$;

CREATE OR REPLACE FUNCTION pg_temp.jp_matrice_by_norm(p_norm text)
RETURNS uuid LANGUAGE plpgsql AS $$
DECLARE v_m uuid;
BEGIN
  SELECT m.id INTO v_m FROM jeupharma.matrice_medicaments m
  JOIN jeupharma.dcis d ON d.id = m.dci_id
  WHERE d.valeur_norm = jeupharma.normaliser_valeur(p_norm) AND m.statut = 'publie' LIMIT 1;
  IF v_m IS NULL THEN RAISE EXCEPTION 'fiche publie introuvable norm=%', p_norm; END IF;
  RETURN v_m;
END $$;

CREATE OR REPLACE FUNCTION pg_temp.jp_detail_set(p_matrice uuid, p_valeur text)
RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  UPDATE jeupharma.matrice_medicaments
  SET detail_pharmacologie_id = pg_temp.jp_ent('details_pharmacologie', p_valeur), updated_at = now()
  WHERE id = p_matrice;
END $$;

DO $mig$
DECLARE
  m uuid;
BEGIN
  -- valsartan (CIS 69593873, scored)
  m := pg_temp.jp_matrice_by_norm('valsartan');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : antagonistes de l’angiotensine II, non associés, code ATC : C09CA03.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Hypertension', 'Traitement de l’hypertension artérielle essentielle chez les adultes, et de l’hypertension chez les enfants et les adolescents âgés de 6 ans à moins de 18 ans.', 'Post-infarctus du myocarde récent', 'Insuffisance cardiaque']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1.', 'Insuffisance hépatique sévère, cirrhose biliaire et cholestase.', 'Deuxième et troisième trimestres de grossesse (voir rubriques 4.4 et 4.6).', 'Utilisation concomitante de VALSARTAN ARROW LAB avec des médicaments contenant de l’aliskiren chez les patients présentant un diabète ou une insuffisance rénale (DFG 2) (voir rubriques 4.5 et 5.1).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Hyperkaliémie', 'Un contrôle du potassium doit être mis en œuvre le cas échéant.', 'Altération de la fonction rénale', 'Il n’y a actuellement pas d’expérience sur l’innocuité du valsartan chez les patients dont la clairance de la créatinine est 10 mL/min (voir rubriques 4.2 et 5.2).', 'Insuffisance hépatique', 'VALSARTAN ARROW LAB doit être utilisé avec prudence chez les patients atteints d’insuffisance hépatique légère à modérée sans cholestase (voir rubriques 4.2 et 5.2).', 'Déplétion sodée et/ou volumique', 'Un déficit sodé et/ou volumique doit être corrigé avant le début d’un traitement par VALSARTAN ARROW LAB, en réduisant par exemple la dose de diurétiques.', 'Sténose de l’artère rénale', 'L’innocuité du valsartan n’a pas été établie chez les patients présentant une sténose bilatérale des artères rénales ou une sténose de l’artère rénale sur rein unique.', 'Un suivi de la fonction rénale est donc recommandé chez les patients traités par valsartan.', 'Transplantation rénale']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Double blocage du système rénine-angiotensine-aldostérone (SRAA) avec les ARA II, les IEC, ou l’aliskiren', 'Associations déconseillées', 'Si cette association est nécessaire, une surveillance stricte de la lithémie est recommandée.', 'Si un diurétique est également utilisé, le risque de toxicité du lithium peut vraisemblablement être augmenté.', 'Diurétiques épargneurs de potassium, suppléments potassiques, substituts du sel contenant du potassium et autres substances pouvant augmenter les taux de potassium', 'Une surveillance des concentrations plasmatiques de potassium est recommandée en cas d''association jugée nécessaire de valsartan avec un médicament agissant sur les taux de potassium.', 'Associations faisant l''objet de précautions d’emploi', 'Anti-inflammatoires non stéroïdiens (AINS), y compris les inhibiteurs sélectifs de la COX-2, l''acide acétylsalicylique à plus de 3 g/jour et les AINS non sélectifs', 'Une atténuation de l''effet antihypertenseur peut survenir en cas d''administration concomitante d''antagonistes de l''angiotensine II et d''AINS.', 'De plus, cette association peut conduire à une augmentation du risque d''altération/aggravation de la fonction rénale et d''augmentation du potassium sérique.', 'Par conséquent, il convient de surveiller la fonction rénale en début de traitement et de maintenir un état d''hydratation approprié du patient.', 'Transporteurs']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Diminution de l’hémoglobine, diminution de l’hématocrite, neutropénie, thrombocytopénie']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Hyperkaliémie', 'Un contrôle du potassium doit être mis en œuvre le cas échéant.', 'Altération de la fonction rénale', 'Il n’y a actuellement pas d’expérience sur l’innocuité du valsartan chez les patients dont la clairance de la créatinine est 10 mL/min (voir rubriques 4.2 et 5.2).', 'Un suivi de la fonction rénale est donc recommandé chez les patients traités par valsartan.']);
  -- candesartan (CIS 61010703, scored)
  m := pg_temp.jp_matrice_by_norm('candesartan');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : antagonistes des récepteurs de l''angiotensine II, code ATC : C09CA06.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['CANDESARTAN ARROW est indiqué dans :', 'traitement de l''hypertension artérielle primaire chez l''adulte ;', 'traitement de l’hypertension chez l’enfant et l’adolescent âgés de 6 à 18 ans ;', 'Le traitement chez l’adulte de l’insuffisance cardiaque avec dysfonction systolique ventriculaire gauche (fraction d’éjection ventriculaire gauche ≤ 40 %) :', 'o en cas d’intolérance aux inhibiteurs de l’enzyme de conversion (IEC)']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité au candésartan cilexetil ou à l''un des excipients mentionnés à la rubrique 6.1.', 'Deuxième et troisième trimestres de la grossesse (voir rubriques 4.4 et 4.6).', 'Insuffisance hépatique sévère et/ou cholestase.', 'Enfant âgé de moins d’un an (voir rubrique 5.3).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Double blocage du système rénine-angiotensine-aldostérone (SRAA)', 'En conséquence, le double blocage du SRAA par l’association d’IEC, d’ARA II ou d’aliskiren, n’est pas recommandé (voir rubriques 4.5 et 5.1).', 'Les IEC et les ARA II ne doivent pas être associés chez les patients atteints d’une néphropathie diabétique.', 'Insuffisance rénale', 'Quand CANDESARTAN ARROW est utilisé chez les patients hypertendus présentant une insuffisance rénale, une surveillance périodique des taux sériques de potassium et de créatinine est recommandée.', 'Lors de l''augmentation de la dose de CANDESARTAN ARROW, il est recommandé de surveiller les taux sériques de potassium et de créatinine.', 'Les essais cliniques réalisés dans l''insuffisance cardiaque n''incluaient aucun patient avec une créatinine sérique > 265 µmol/l (> 3 mg/dL).', 'Population pédiatrique, incluant les patients pédiatriques présentant une atteinte de la fonction rénale', 'Le candésartan n''a pas été étudié chez des enfants présentant un débit de filtration glomérulaire inférieur à 30 mL/min/1,73 m2 (voir rubrique 4.2).', 'Traitement associé à un inhibiteur de l''enzyme de conversion (IEC) dans l''insuffisance cardiaque', 'La triple association d''un IEC, d’un antagoniste de l’aldostérone et du candésartan n''est pas recommandée.', 'L’utilisation de ces associations doit être faite sous le contrôle d’un spécialiste et il faut surveiller régulièrement la fonction rénale, l’ionogramme sanguin et la pression artérielle.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Aucune interaction pharmacocinétique cliniquement significative avec ces médicaments n''a été identifiée.', 'Une surveillance régulière de la kaliémie doit être effectuée le cas échéant (voir rubrique 4.4).', 'Des augmentations réversibles des concentrations sériques de lithium et de la toxicité ont été observées au cours de l''administration concomitante de lithium et d''inhibiteurs de l''enzyme de conversion (IEC).', 'Un effet similaire peut survenir avec les ARAII.', 'L''utilisation du candésartan et du lithium n''est pas recommandée.', 'Si l''association est indispensable, une surveillance attentive des taux sériques de lithium est recommandée.', 'L''association doit être utilisée avec prudence, en particulier chez les patients âgés.', 'Les patients doivent être hydratés correctement et une surveillance de la fonction rénale sera mise en place à l''initiation du traitement concomitant, puis périodiquement par la suite.', 'Population pédiatrique', 'Les études d''interactions n''ont été réalisées que chez l''adulte.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les fréquences utilisées dans les tableaux de la rubrique 4.8 sont les suivantes : très fréquent (≥ 1/10), fréquent (≥ 1/100 à', 'Fréquent']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Quand CANDESARTAN ARROW est utilisé chez les patients hypertendus présentant une insuffisance rénale, une surveillance périodique des taux sériques de potassium et de créatinine est recommandée.', 'Lors de l''augmentation de la dose de CANDESARTAN ARROW, il est recommandé de surveiller les taux sériques de potassium et de créatinine.', 'Les essais cliniques réalisés dans l''insuffisance cardiaque n''incluaient aucun patient avec une créatinine sérique > 265 µmol/l (> 3 mg/dL).', 'Population pédiatrique, incluant les patients pédiatriques présentant une atteinte de la fonction rénale', 'L’utilisation de ces associations doit être faite sous le contrôle d’un spécialiste et il faut surveiller régulièrement la fonction rénale, l’ionogramme sanguin et la pression artérielle.']);
  -- digoxine (CIS 63593820, scored)
  m := pg_temp.jp_matrice_by_norm('digoxine');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : GLUCOSIDE CARDIOTONIQUE code ATC : C01AA05 (Système cardiovasculaire).');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Insuffisance cardiaque.', 'troubles du rythme supraventriculaire: ralentissement ou réduction de la fibrillation auriculaire ou du flutter auriculaire.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1', 'Ce médicament ne doit jamais être utilisé en cas de :', 'blocs auriculo-ventriculaires du 2ème et du 3ème degré non appareillés,', 'hyperexcitabilité ventriculaire (notamment extrasystoles) survenant quand le malade est encore sous l''action d''un digitalique (voir rubrique 4.4),', 'tachycardies atriales (flutter, tachysystolie) et fibrillation auriculaire associée à un syndrome de Wolff-Parkinson-White,', 'tachycardie et fibrillation ventriculaires,', 'hypokaliémie non corrigée,', 'association au sultopride, au calcium (sels de) voie IV, au millepertuis (voir rubrique 4.5).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mises en garde', 'L''arrêt des digitaliques est impératif en cas d''hyperexcitabilité ventriculaire (notamment extrasystoles) liée à une hypersensibilité, à un surdosage ou à une hypokaliémie.', 'Il est conseillé d''arrêter le traitement 3 jours (2 demi-vies) avant un choc électrique.', 'Ce médicament est généralement déconseillé en association à la midodrine (voir rubrique 4.5).', 'Les patients présentant une intolérance au galactose, un déficit total en lactase ou un syndrome de malabsorption du glucose et du galactose (maladies héréditaires rares) ne doivent pas prendre ce médicament.', 'Précautions d''emploi', 'Ce médicament doit être utilisé avec prudence en cas de cardiomyopathie hypertrophique et cardiomyopathie restrictive.', 'Une surveillance attentive du traitement, avec contrôle ECG, est recommandée, en particulier en cas de:', 'insuffisance rénale sévère; il est alors nécessaire d''ajuster la posologie en fonction de la clairance de la créatinine,', 'insuffisance hépatique sévère.', 'Une surveillance clinique et électrocardiographique attentive est également recommandée en début de traitement:', 'dans les insuffisances cardiaques avec B.A.V. du 1° degré,']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Médicaments bradycardisants', 'De nombreux médicaments peuvent entraîner une bradycardie.', 'C''est le cas notamment des antiarythmiques de classe Ia, des bêta-bloquants, de certains antiarythmiques de classe III, de certains antagonistes du calcium, des anticholinestérasiques, de la pilocarpine etc.', 'Associations contre-indiquées', '(voir rubrique 4.3)', '+ Calcium (sels de) (voie I.V.)', 'Risque de troubles du rythme graves, voire mortels.', '+ Millepertuis', 'En cas d''association fortuite, ne pas interrompre brutalement la prise de millepertuis mais contrôler les concentrations plasmatiques (ou l''efficacité) de la digoxine avant puis après l''arrêt du millepertuis.', '+ Sultopride', 'Risque majoré de trouble du rythme ventriculaire, notamment de torsades de pointes.', 'Associations déconseillées']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les troubles digestifs (nausées, vomissements, diarrhées), sont les premiers symptômes fréquents et précoces de la toxicité digitalique.']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['L''arrêt des digitaliques est impératif en cas d''hyperexcitabilité ventriculaire (notamment extrasystoles) liée à une hypersensibilité, à un surdosage ou à une hypokaliémie.', 'Une surveillance attentive du traitement, avec contrôle ECG, est recommandée, en particulier en cas de:', 'insuffisance rénale sévère; il est alors nécessaire d''ajuster la posologie en fonction de la clairance de la créatinine,', 'Une surveillance clinique et électrocardiographique attentive est également recommandée en début de traitement:']);
  -- furosemide (CIS 63736250, scored)
  m := pg_temp.jp_matrice_by_norm('furosemide');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : DIURETIQUE DE L''ANSE, code ATC : C03CA01.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Œdèmes d''origine cardiaque ou rénale.', 'Œdèmes d''origine hépatique, le plus souvent en association avec un diurétique épargneur de potassium.', 'Hypertension artérielle.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Ce médicament NE DOIT JAMAIS être utilisé en cas d’ :', 'Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1.', 'Insuffisance rénale aiguë fonctionnelle.', 'Encéphalopathie hépatique.', 'Obstruction sur les voies urinaires.', 'Hypovolémie ou déshydratation.', 'Hypokaliémie sévère (voir rubrique 4.8).', 'Hyponatrémie sévère.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mises en garde spéciales', 'Avec le lithium, l’association est déconseillée (voir rubrique 4.5).', 'La prise accidentelle de furosémide peut entraîner une hypovolémie avec déshydratation (voir rubrique 4.9).', 'Chez l’insuffisant hépatocellulaire, le traitement sera conduit avec prudence sous surveillance hydroélectrolytique stricte, compte tenu d’un risque d’encéphalopathie hépatique (cf.', 'Précautions d’emploi).', 'L’interruption du traitement devra alors être immédiate.', 'La prise de furosémide en cas d’obstruction partielle des voies urinaires peut exposer les patients à une rétention urinaire.', 'Une surveillance étroite de la diurèse devra donc être instaurée, particulièrement en début de traitement par le furosémide.', 'Le furosémide est un sulfamide.', 'La possibilité d’une allergie croisée avec les autres sulfamides, notamment antibactériens, reste théorique et non validée en clinique.', 'Des cas de réactions de photosensibilité ont été rapportés avec le furosémide (voir rubrique 4.8).', 'En cas de survenue de réactions de photosensibilité sous traitement, il est recommandé d’interrompre le traitement.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Interaction liée à la présence d’éthanol', 'Médicaments hypokaliémiants', 'L''hypokaliémie est un facteur favorisant l''apparition de troubles du rythme cardiaque (torsades de pointes notamment) et augmentant la toxicité de certains médicaments, par exemple la digoxine.', 'De ce fait, les médicaments qui peuvent entraîner une hypokaliémie sont impliqués dans un grand nombre d''interactions.', 'Il s''agit des diurétiques hypokaliémiants, seuls ou associés, des laxatifs stimulants, des glucocorticoïdes, du tétracosactide et de l''amphotéricine B (voie IV).', 'Médicaments hyponatrémiants', 'Certains médicaments sont plus fréquemment impliqués dans la survenue d''une hyponatrémie.', 'Ce sont les diurétiques, la desmopressine, les antidépresseurs inhibant la recapture de la sérotonine, la carbamazépine et l''oxcarbazépine.', 'L''association de ces médicaments majore le risque d''hyponatrémie.', 'Médicaments ototoxiques', 'L''utilisation conjointe de médicaments ayant une ototoxicité augmente le risque d''atteinte cochléo-vestibulaire.', 'Si une telle association est nécessaire, il convient de renforcer la surveillance de la fonction auditive.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Quand cela est possible, la fréquence des effets indésirables est définie selon la convention suivante : très fréquent (≥10%), fréquent (≥1 à', 'Très fréquent', 'Fréquent', 'Peu fréquent']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Chez l’insuffisant hépatocellulaire, le traitement sera conduit avec prudence sous surveillance hydroélectrolytique stricte, compte tenu d’un risque d’encéphalopathie hépatique (cf.', 'Une surveillance étroite de la diurèse devra donc être instaurée, particulièrement en début de traitement par le furosémide.']);
  -- spironolactone (CIS 63145849, scored)
  m := pg_temp.jp_matrice_by_norm('spironolactone');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : diurétiques épargneurs potassiques, code ATC : C03DA01.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Chez l’adulte et l’enfant', 'Traitement de l''hyperaldostéronisme primaire.', 'Hyperaldostéronisme réactionnel à un traitement diurétique efficace.', 'Hypertension artérielle essentielle.', 'Etats œdémateux pouvant s''accompagner d''un hyperaldostéronisme secondaire :', 'œdème et ascite de l''insuffisance cardiaque,', 'syndrome néphrotique,', 'ascite cirrhotique.', 'Thérapeutique adjuvante de la myasthénie : dans cette indication, la spironolactone est une médication permettant de maintenir le capital potassique et de diminuer les besoins exagérés de potassium.', 'Chez l''adulte seulement', 'Le traitement par la spironolactone 25 mg au long cours associé au traitement de fond ci-dessus a significativement amélioré la survie dans l''étude Rales (voir rubrique 5.1).', 'La spironolactone est indiquée dans le traitement de l’hirsutisme, seule ou en association avec d’autres médicaments.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Ce médicament ne doit jamais être utilisé en cas de :', 'hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1 ;', 'insuffisance rénale sévère ou aiguë notamment : anurie, dysfonctionnement rénal à évolution rapide ;', 'insuffisance rénale modérée chez l’enfant ;', 'maladie d’Addison ;', 'hyperkaliémie ;', 'stade terminal de l''insuffisance hépatique ;', 'association à d''autres diurétiques épargneurs de potassium (seuls ou associés) tels que : amiloride, canrénoate de potassium, éplérénone, triamtérène sauf s’il existe une hypokaliémie (voir rubrique 4.5) ;', 'association au mitotane (voir rubrique 4.5).', 'Ce médicament est généralement déconseillé :', 'chez le cirrhotique quand la natrémie est inférieure à 125 mmol/L ;', 'chez les sujets susceptibles de présenter une acidose.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Hyperkaliémie', 'L''utilisation concomitante de médicaments connus pour provoquer une hyperkaliémie avec la spironolactone peut entraîner une hyperkaliémie sévère.', 'Toute prescription d''un médicament agissant sur le système rénine-angiotensine-aldostérone est susceptible de provoquer une hyperkaliémie.', 'Avant d''envisager une association de plusieurs médicaments bloquant le système rénine-angiotensine-aldostérone, il faut évaluer soigneusement le rapport bénéfice/risque et l''existence d''alternatives éventuelles.', 'Les principaux facteurs de risque d''hyperkaliémie à prendre en considération sont :', 'diabète, altération de la fonction rénale, âge (> 70 ans), autres affections connues à l’origine d’hyperkaliémie ;', 'association avec un ou plusieurs autres médicaments bloquant le système rénine-angiotensine-aldostérone et/ou d''autres médicaments hyperkaliémiants et/ou de suppléments potassiques.', 'Le suivi des patients, et notamment des patients à risque, devra comporter un ionogramme sanguin, avec en particulier un contrôle de la kaliémie, de la natrémie, et de la fonction rénale :', 'avant l''instauration du traitement puis une semaine à 15 jours après ;', 'de même (avant et après) chaque augmentation de dose ou modification de traitement.', 'Puis en traitement d''entretien, les contrôles devront être réalisés régulièrement OU lors de la survenue d''un événement intercurrent.', 'Un bilan hépatique est indispensable chez les malades graves.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['L''association de ces médicaments majore le risque d''hyperkaliémie.', 'Pour connaître les risques et les niveaux de contrainte spécifiques aux médicaments hyperkaliémiants, il convient de se reporter aux interactions propres à chaque substance.', 'Certaines substances ne font pas l''objet d''interactions spécifiques au regard de ce risque.', 'Néanmoins, ils peuvent agir comme facteurs favorisants lorsqu''ils sont associés à d''autres médicaments déjà mentionnés dans cette rubrique.', 'Associations contre-indiquées', '+ Autres diurétiques épargneurs de potassium (seuls ou associés) (amiloride, canrénoate de potassium, éplérénone, triamtérène)', 'Hyperkaliémie potentiellement létale notamment chez l''insuffisant rénal (addition des effets hyperkaliémiants).', 'Contre-indiquée sauf s’il existe une hypokaliémie.', '+ Mitotane', 'La spironolactone peut réduire les concentrations plasmatiques de mitotane chez les patients présentant un carcinome corticosurrénalien traités par le mitotane et ne doit pas être utilisée simultanément au mitotane.', 'Risque de blocage de l’action du mitotane par la spironolactone.', 'Associations déconseillées']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les effets indésirables rapportés au cours des essais cliniques et après la commercialisation sont présentés dans le tableau ci-dessous, selon leur fréquence : très fréquent (³ 1/10) ; fréquent (³ 1/1', 'Très fréquent', 'Fréquent', '³ 1/100 à', 'Peu fréquent', '³ 1/10 000 à', 'Tumeurs bénignes, malignes et non spécifiées (y compris kystes et polypes)']);
