  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Anesthésiques halogénés volatils : arythmie ventriculaire grave (augmentation de l’excitabilité cardiaque).', 'Antidépresseurs imipraminiques : hypertension paroxystique avec possibilité d’arythmie (inhibition de l’entrée des sympathomimétiques dans les fibres sympathiques).', 'Antidépresseurs sérotoninergiques-adrénergiques : hypertension paroxystique avec possibilité d’arythmie (inhibition de l’entrée des sympathomimétiques dans les fibres sympathiques).', 'Agents sympathomimétiques : l’administration concomitante d’autres sympathomimétiques pourrait augmenter la toxicité en raison des effets additifs possibles.', 'IMAO non sélectifs : augmentation de l’action vasopressive de l’adrénaline, habituellement modérée.', 'IMAO-A sélectifs, linézolide (par extrapolation à partir des IMAO non sélectifs) : Risque d’aggravation de l’action vasopressive.', 'Alpha-bloquants adrénergiques : Les alphabloquants antagonisent les effets vasopressifs et hypertenseurs de l’adrénaline, ce qui augmente le risque d’hypotension et de tachycardie.', 'Bêta-bloquants adrénergiques : Une hypertension artérielle sévère et une bradycardie réflexe peuvent survenir avec des agents bêtabloquants non-cardiosélectifs.', 'Les bêtabloquants, en particulier les agents non-cardiosélectifs, antagonisent également les effets cardiaques et bronchodilatateurs de l’adrénaline.', 'Insuline ou hypoglycémiants oraux : L’hyperglycémie provoquée par l’adrénaline peut conduire à une perte de la maîtrise de la glycémie chez les patients diabétiques traités par insuline ou par hypoglycémiants oraux.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['À haute dose ou chez les patients sensibles à l’adrénaline : arythmie cardiaque (tachycardie sinusale, fibrillation ventriculaire/arrêt cardiaque), crises angineuses et risque d’infarctus aigu du myoc']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Les patients qui reçoivent de l’adrénaline IV nécessitent au minimum une surveillance continue de l’ECG, de l’oxymétrie de pouls et mesures fréquentes de la tension artérielle.', 'Hypokaliémie']);
